operations.schema:
input RemoveDeliverableInput {
  id: OID!
}

input SetDeliverableProgressInput {
  id: OID! #deliverable id
  workProgress: ProgressInput
}

input ProgressInput {
  # Only one of these fields should be provided
  percentage: Float
  storyPoints: StoryPointInput
  done: Boolean
}

input StoryPointInput {
  total: Int!
  completed: Int!
}

input AddKeyResultInput {
  id: OID!
  deliverableId:OID!
  title: String!
  link: String
}

input RemoveKeyResultInput {
  id: OID!
  deliverableId:OID!
}

input EditKeyResultInput {
  id: OID!
  deliverableId: OID!
  title: String
  link: URL
}

input LinkDeliverableGoalInput {
  deliverableId: OID!
  # a goal in the anchoring project's WBS; omit or null to unlink
  goalRef: OID
}

input AddRoadmapInput {
  id: OID!
  title: String!
  slug: String
  description: String
}

input RemoveRoadmapInput {
  id: OID!
}

input RemoveMilestoneInput {
  id: OID!
  roadmapId:OID!
}

input AddCoordinatorInput {
  id: ID! 
  milestoneId: OID!
}

input RemoveCoordinatorInput {
  id: ID! 
  milestoneId: OID! # Coordinator can potentially be coordinating multiple milestones/roadmaps. 
}

input AddMilestoneDeliverableInput {
  milestoneId: OID!
  deliverableId: OID!
  title: String!
}

input RemoveMilestoneDeliverableInput {
  milestoneId: OID!
  deliverableId: OID!
}

input EditDeliverablesSetInput {
  milestoneId: ID
  projectId: ID
  status: DeliverableSetStatusInput
  deliverablesCompleted: DeliverablesCompletedInput
}

enum DeliverableSetStatusInput {
  DRAFT
  TODO
  IN_PROGRESS
  FINISHED
  CANCELED
}

input DeliverablesCompletedInput {
  total: Int!
  completed: Int!
}

input AddDeliverableInSetInput {
  milestoneId: ID
  projectId: ID
  deliverableId: OID!
}

input RemoveDeliverableInSetInput {
  milestoneId: ID
  projectId: ID
  deliverableId: OID!
}

input AddAgentInput {
  id: PHID!
  name: String!
  icon: URL
  description: String
}

input RemoveAgentInput {
  id: PHID!
}

input EditAgentInput {
  id: PHID!
  name: String
  icon: URL
  description: String
}

input UpdateProjectOwnerInput {
  id: OID! # The ID of the project
  projectOwner: ID! # The ID of the new owner (Agent)
}

input RemoveProjectInput {
  projectId: ID!
}

input SetProjectMarginInput {
  projectId: OID!
  margin: Float!
}

input SetProjectTotalBudgetInput {
  projectId: OID!
  totalBudget: Float!
}

input AddProjectDeliverableInput {
  projectId: OID!
  deliverableId: ID!
  title: String!
}

input RemoveProjectDeliverableInput {
  projectId: OID!
  deliverableId: OID!
}

input SetProjectExpenditureInput {
  projectId: OID!
  actuals: Float
  cap: Float
}

input LinkProjectWbsInput {
  projectId: OID!
  # the bai/wbs document that delivers this project; omit or null to unlink
  wbsRef: PHID
}

input AddProjectKnowledgeRefInput {
  projectId: OID!
  # a bai/knowledge-note or bai/moc in the same drive
  ref: PHID!
}

input RemoveProjectKnowledgeRefInput {
  projectId: OID!
  ref: PHID!
}

input SetProjectReferencesInput {
  projectId: OID!
  # replaces the whole list, as bai/project's SET_REFERENCES does
  references: [URL!]!
}
